def solve(data):
    n = data["n"]
    edges = data["edges"]
    source = data["source"]
    target = data["target"]
    k = data["k"]

    if k == 0:
        return 0 if source == target else None

    bits = k.bit_length()
    if k * len(edges) <= n * n * n * bits:
        dist = [None] * n
        dist[source] = 0

        for step in range(k):
            nxt = dist[:]
            changed = False

            for edge in edges:
                u, v, weight = edge
                cost = dist[u]
                if cost is not None:
                    candidate = cost + weight
                    if nxt[v] is None or candidate < nxt[v]:
                        nxt[v] = candidate
                        changed = True

            dist = nxt
            if not changed:
                break

        return dist[target]

    matrix = [[None] * n for row in range(n)]
    for i in range(n):
        matrix[i][i] = 0

    for edge in edges:
        u, v, weight = edge
        current = matrix[u][v]
        if current is None or weight < current:
            matrix[u][v] = weight

    vector = [None] * n
    vector[source] = 0

    while k:
        if k & 1:
            result = [None] * n
            for i in range(n):
                base = vector[i]
                if base is None:
                    continue
                row = matrix[i]
                for j in range(n):
                    weight = row[j]
                    if weight is not None:
                        candidate = base + weight
                        if result[j] is None or candidate < result[j]:
                            result[j] = candidate
            vector = result

        k //= 2
        if not k:
            break

        squared = [[None] * n for row in range(n)]
        for i in range(n):
            output_row = squared[i]
            for middle in range(n):
                left = matrix[i][middle]
                if left is None:
                    continue
                right_row = matrix[middle]
                for j in range(n):
                    right = right_row[j]
                    if right is not None:
                        candidate = left + right
                        if output_row[j] is None or candidate < output_row[j]:
                            output_row[j] = candidate
        matrix = squared

    return vector[target]

