def solve(data):
    source = data["source"]
    target = data["target"]
    k = data["k"]

    if k == 0:
        return 0 if source == target else None

    graph = {}
    for u, v, weight in data["edges"]:
        if u == v and weight >= 0:
            continue
        row = graph.get(u)
        if row is None:
            row = {}
            graph[u] = row
        old = row.get(v)
        if old is None or weight < old:
            row[v] = weight

    reverse = {}
    for u, row in graph.items():
        for v in row:
            reverse.setdefault(v, []).append(u)

    can_reach = {target: True}
    stack = [target]
    while stack:
        v = stack.pop()
        for u in reverse.get(v, []):
            if u not in can_reach:
                can_reach[u] = True
                stack.append(u)

    if source not in can_reach:
        return None

    rows = {}
    seen = {source: True}
    stack = [source]
    while stack:
        u = stack.pop()
        row = graph.get(u)
        if row is None:
            continue
        kept = {}
        for v, weight in row.items():
            if v in can_reach:
                kept[v] = weight
                if v not in seen:
                    seen[v] = True
                    stack.append(v)
        if kept:
            rows[u] = kept

    if not rows:
        return 0 if source == target else None

    edge_count = sum(len(row) for row in rows.values())
    work_limit = 64 * edge_count

    if k > 64:
        square_work = 0
        for row in rows.values():
            for v in row:
                next_row = rows.get(v)
                if next_row is not None:
                    square_work += len(next_row)

        bits = 0
        value = k
        while value:
            bits += 1
            value //= 2

        if k * edge_count <= (square_work + edge_count) * bits:
            work_limit = k * edge_count + 1

    distance = {source: 0}
    frontier = {source: 0}
    remaining = k
    work = 0

    while remaining and frontier and work < work_limit:
        next_frontier = {}
        for u, cost in frontier.items():
            row = rows.get(u)
            if row is None:
                continue
            work += len(row)
            for v, weight in row.items():
                candidate = cost + weight
                old = distance.get(v)
                if old is None or candidate < old:
                    distance[v] = candidate
                    next_frontier[v] = candidate
        frontier = next_frontier
        remaining -= 1

    if not remaining or not frontier:
        return distance.get(target)

    def advance(current, matrix):
        result = current.copy()
        for u, cost in current.items():
            row = matrix.get(u)
            if row is None:
                continue
            for v, weight in row.items():
                candidate = cost + weight
                old = result.get(v)
                if old is None or candidate < old:
                    result[v] = candidate
        return result

    while remaining:
        if remaining % 2:
            distance = advance(distance, rows)

        remaining //= 2
        if not remaining:
            break

        squared = {}
        changed = False
        for u, row in rows.items():
            result = row.copy()
            for middle, left in row.items():
                next_row = rows.get(middle)
                if next_row is None:
                    continue
                for v, right in next_row.items():
                    candidate = left + right
                    if u == v and candidate >= 0:
                        continue
                    old = result.get(v)
                    if old is None or candidate < old:
                        result[v] = candidate
                        changed = True
            squared[u] = result

        if not changed:
            return advance(distance, rows).get(target)

        rows = squared

    return distance.get(target)

