        for _ in range(k):
            updated = distances.copy()
            for u, v, weight in edges:
                if u in distances:
                    cost = distances[u] + weight
                    if v not in updated or cost < updated[v]:
                        updated[v] = cost
            if updated == distances:
                break
            distances = updated
