    while k:
        if k % 2:
            updated = distances.copy()
            for u, cost in distances.items():
                row = matrix.get(u)
                if row is not None:
                    for v, weight in row.items():
                        candidate = cost + weight
                        if v not in updated or candidate < updated[v]:
                            updated[v] = candidate
            distances = updated

